function Test-Port($port){ try { $c=New-Object System.Net.Sockets.TcpClient; $c.Connect('127.0.0.1',$port); $c.Close(); $true } catch { $false } }
for($i=0;$i -lt 90;$i++){
  $g=Test-Port 8086; $p=Test-Port 9222
  if($g -and $p){ Write-Host "BOTH_UP iter=$i (~$($i*2)s)"; break }
  if($i % 10 -eq 0){ Write-Host "waiting... iter=$i gw=$g pt=$p" }
  Start-Sleep -Seconds 2
}
Start-Sleep -Seconds 6
Write-Host "== 8091 apps =="; curl.exe -s -o $null -w "http=%{http_code}`n" --max-time 10 http://localhost:8091/api/v3.0/portal/appLogin/apps
Write-Host "== 8091 root =="; curl.exe -s -o $null -w "http=%{http_code}`n" --max-time 10 http://localhost:8091/
Write-Host "DONE"

